type StudyAnswerUndoMeta = {
  cardId: string;
  result: BinaryStudyResult;
  mode: "study" | "cram";
  durationMs: number;
  reviewedAt: string;
  sessionId: string;
};

function studyAnswerUndoKey(meta: StudyAnswerUndoMeta) {
  return [
    meta.sessionId,
    meta.cardId,
    meta.mode,
    meta.result,
    meta.reviewedAt,
  ].join("|");
}

function isCardReviewState(value: unknown): value is CardReviewState {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<CardReviewState>;
  return (
    typeof candidate.cardId === "string" &&
    (candidate.bucket === "learn" || candidate.bucket === "due") &&
    typeof candidate.lastReviewedAt === "string" &&
    typeof candidate.dueAt === "string"
  );
}

function sameStudyReviewInstant(left: string, right: string) {
  if (left === right) return true;
  const leftMs = Date.parse(left);
  const rightMs = Date.parse(right);
  return Number.isFinite(leftMs) && leftMs === rightMs;
}

function matchesStudyAnswerUndo(log: StudyReviewLog, meta: StudyAnswerUndoMeta) {
  return (
    log.cardId === meta.cardId &&
    log.mode === meta.mode &&
    log.result === meta.result &&
    (log.sessionId ?? null) === meta.sessionId &&
    sameStudyReviewInstant(log.reviewedAt, meta.reviewedAt)
  );
}

