function formatDeckCount(count: number) {
  return count > 999 ? "999+" : String(count);
}

const ACTION_MENU_WIDTH = 176;
const ACTION_MENU_HEIGHT = 194;

function CountCell({
  value,
  activeClassName,
}: {
  value: number;
  activeClassName: string;
}) {
  return (
    <div
      className={cn(
        "w-full pr-1 text-right text-sm font-semibold tabular-nums",
        value > 0 ? activeClassName : "text-muted-foreground/60",
      )}
    >
      {formatDeckCount(value)}
    </div>
  );
}

function MobileStatPill({
  label,
  value,
  activeClassName,
}: {
  label: string;
  value: number;
  activeClassName: string;
}) {
  return (
    <div
      className={cn(
        "inline-flex items-center gap-1 rounded-full border px-2 py-1 text-[11px] font-semibold leading-none shadow-[0_1px_0_rgb(15_23_42_/_0.04)]",
        value > 0
          ? "border-border bg-background text-foreground"
          : "border-transparent bg-muted/45 text-muted-foreground/70",
      )}
    >
      <span>{label}</span>
      <span
        className={cn(
          "min-w-4 text-right tabular-nums",
          value > 0 ? activeClassName : "text-muted-foreground/60",
        )}
      >
        {formatDeckCount(value)}
      </span>
    </div>
  );
}

function TimeCell({ row }: { row: DeckBrowserRow }) {
  const totalMs = getStudyTimeTotalMs(row);
  const breakdown = formatStudyTimeBreakdown(row);
  return (
    <div
      className={cn(
        "w-full pr-1 text-right text-xs font-semibold leading-tight tabular-nums",
        totalMs > 0 ? "text-foreground" : "text-muted-foreground/60",
      )}
      title={breakdown}
    >
      <div>{formatStudyTime(totalMs)}</div>
      {totalMs > 0 ? (
        <div className="truncate text-[10px] font-medium text-muted-foreground">
          {breakdown}
        </div>
      ) : null}
    </div>
  );
}

function EstimateCell({ row }: { row: DeckBrowserRow }) {
  const estimate = row.studyEstimate;
  return (
    <div
      className={cn(
        "w-full pr-1 text-right text-xs font-semibold leading-tight tabular-nums",
        estimate && estimate.estimatedMs > 0 ? "text-foreground" : "text-muted-foreground/60",
      )}
      title={formatStudyTimeEstimateRange(estimate)}
    >
      <div>{formatStudyTimeEstimate(estimate)}</div>
      {estimate && estimate.estimatedMs > 0 ? (
        <div className="truncate text-[10px] font-medium text-muted-foreground">
          {formatStudyTimeEstimateRange(estimate)}
        </div>
      ) : null}
    </div>
  );
}

