) {
  return {
    id,
    folderId: tagIds[0] ?? null,
    parentCardId: null,
    folderPath: tagNames.join(' • '),
    folderPathIds: [...tagIds],
    folderPathNames: [...tagNames],
    tagIds: [...tagIds],
    tagNames: [...tagNames],
    tagPaths: [...tagNames],
    question,
    answer: `${question} answer`,
    createdAt,
    updatedAt,
  }
}

