import { describe, expect, it, vi } from "vitest";
import { DeckBrowserTable } from "./DeckBrowserTable";

const baseTag = {
  id: "tag-bio",
  name: "Biology",
  parentId: null,
  createdAt: "2026-04-14T00:00:00.000Z",
  updatedAt: "2026-04-14T00:00:00.000Z",
};

const baseRow = {
  id: "biology",
  title: "Biology",
  fullPath: "Biology",
  depth: 0,
  ancestorIds: [],
  hasChildren: false,
  actualTag: baseTag,
  descendantTagIds: ["tag-bio"],
  totalCards: 2,
  newCount: 0,
  learnCount: 1,
  dueCount: 1,
} as const;

describe("DeckBrowserTable", () => {
  it("shows Reset study in the folder action menu and calls the reset handler", () => {
    const onResetDeck = vi.fn();

    render(
      <DeckBrowserTable
        rows={[baseRow]}
        selectedDeckKey=""
        onSelectDeck={vi.fn()}
        onAddSubdeck={vi.fn()}
        onRenameTag={vi.fn()}
        onResetDeck={onResetDeck}
        onDeleteTag={vi.fn()}
      />,
    );

    fireEvent.click(screen.getByRole("button", { name: "Open folder actions for Biology" }));

    const resetButton = screen.getByRole("menuitem", { name: "Reset study" });
    expect(resetButton).toBeEnabled();

    fireEvent.click(resetButton);

    expect(onResetDeck).toHaveBeenCalledWith(baseRow);
  });

  it("labels the browser heading as Decks", () => {
    render(
      <DeckBrowserTable
        rows={[baseRow]}
        selectedDeckKey=""
        onSelectDeck={vi.fn()}
        onAddSubdeck={vi.fn()}
        onRenameTag={vi.fn()}
        onResetDeck={vi.fn()}
        onDeleteTag={vi.fn()}
      />,
    );

    expect(screen.getByText("Decks")).toBeInTheDocument();
  });

  it("shows due counts in the compact mobile stats", () => {
    render(
      <DeckBrowserTable
        rows={[baseRow]}
        selectedDeckKey=""
        onSelectDeck={vi.fn()}
        onAddSubdeck={vi.fn()}
        onRenameTag={vi.fn()}
        onResetDeck={vi.fn()}
        onDeleteTag={vi.fn()}
      />,
    );

    expect(screen.getAllByText("Due")).toHaveLength(2);
  });

  it("shows an empty state when no decks match", () => {
    render(
      <DeckBrowserTable
        rows={[]}
        selectedDeckKey=""
        onSelectDeck={vi.fn()}
        onAddSubdeck={vi.fn()}
        onRenameTag={vi.fn()}
        onResetDeck={vi.fn()}
        onDeleteTag={vi.fn()}
      />,
    );

    expect(screen.getByText("No matching decks")).toBeInTheDocument();
  });

  it("disables Reset study when the folder has no saved study progress", () => {
    render(
      <DeckBrowserTable
        rows={[
          {
            ...baseRow,
            learnCount: 0,
            dueCount: 0,
            newCount: 2,
          },
        ]}
        selectedDeckKey=""
        onSelectDeck={vi.fn()}
        onAddSubdeck={vi.fn()}
        onRenameTag={vi.fn()}
        onResetDeck={vi.fn()}
        onDeleteTag={vi.fn()}
      />,
    );

    fireEvent.click(screen.getByRole("button", { name: "Open folder actions for Biology" }));

    expect(screen.getByRole("menuitem", { name: "Reset study" })).toBeDisabled();
  });

  it("shows Add subdeck in the folder action menu and calls the handler", () => {
    const onAddSubdeck = vi.fn();

    render(
      <DeckBrowserTable
        rows={[baseRow]}
        selectedDeckKey=""
        onSelectDeck={vi.fn()}
        onAddSubdeck={onAddSubdeck}
        onRenameTag={vi.fn()}
        onResetDeck={vi.fn()}
        onDeleteTag={vi.fn()}
      />,
    );

    fireEvent.click(screen.getByRole("button", { name: "Open folder actions for Biology" }));
    fireEvent.click(screen.getByRole("menuitem", { name: "Add subdeck" }));

    expect(onAddSubdeck).toHaveBeenCalledWith(baseTag);
  });
});

