import * as React from 'react'
import {
  Links,
  Meta,
  Outlet,
  Scripts,
  ScrollRestoration,
  isRouteErrorResponse,
  useRouteLoaderData,
} from 'react-router'
import type { LoaderFunctionArgs } from 'react-router'
import { AppProviders } from '@/shared/app/AppProviders'
import { AppShell } from '@/shared/app/AppShell'
import { ReactRouterAppRoutingBridge } from '@/app/components/ReactRouterAppRoutingBridge'
import {
  SITE_DESCRIPTION,
  SITE_CANONICAL_PATH,
  SITE_FONT_FAMILY,
  SITE_NAME,
  SITE_OG_ALT,
  SITE_SOCIAL_IMAGE_PATH,
  SITE_TAGLINE,
  SITE_TITLE,
  SITE_URL,
} from '@/shared/app/siteMetadata'
import '@fontsource-variable/inter'
import '@/app.css'

type RootLoaderData = {
  publicEnv: {
    SIMPLECARDS_AUTH_CONFIGURED: boolean
  }
}

function serializeScriptData(value: unknown) {
  return JSON.stringify(value).replace(/</g, '\\u003c')
}

export function loader({ context }: LoaderFunctionArgs): RootLoaderData {
  return {
    publicEnv: {
      SIMPLECARDS_AUTH_CONFIGURED: Boolean(
        context.cloudflare.env.SIMPLECARDS_SUPABASE_URL &&
        context.cloudflare.env.SIMPLECARDS_SUPABASE_PUBLISHABLE_KEY &&
        context.cloudflare.env.SIMPLECARDS_BFF_SESSION_SECRET,
      ),
    },
  }
}

export function links() {
  return [
    { rel: 'canonical', href: new URL(SITE_CANONICAL_PATH, SITE_URL).toString() },
    { rel: 'icon', href: '/nocards-favicon-v4.svg', type: 'image/svg+xml' },
  ]
}

export function meta() {
  const socialImageUrl = new URL(SITE_SOCIAL_IMAGE_PATH, SITE_URL).toString()

  return [
    { title: SITE_TITLE },
    { name: 'description', content: SITE_DESCRIPTION },
    { name: 'application-name', content: SITE_NAME },
    { property: 'og:type', content: 'website' },
    { property: 'og:url', content: SITE_URL },
    { property: 'og:site_name', content: SITE_NAME },
    { property: 'og:title', content: SITE_TITLE },
    { property: 'og:description', content: SITE_TAGLINE },
    { property: 'og:image', content: socialImageUrl },
    { property: 'og:image:alt', content: SITE_OG_ALT },
    { name: 'twitter:card', content: 'summary_large_image' },
    { name: 'twitter:title', content: SITE_TITLE },
    { name: 'twitter:description', content: SITE_TAGLINE },
    { name: 'twitter:image', content: socialImageUrl },
  ]
}

export function Layout({ children }: { children: React.ReactNode }) {
  const loaderData = useRouteLoaderData<RootLoaderData>('root')
  const publicEnv = loaderData?.publicEnv ?? {
    SIMPLECARDS_AUTH_CONFIGURED: false,
  }

  return (
    <html lang="en" style={{ '--font-body': SITE_FONT_FAMILY } as React.CSSProperties}>
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <Meta />
        <Links />
      </head>
      <body>
        <script
          dangerouslySetInnerHTML={{
            __html: `window.__SIMPLECARDS_ENV__ = ${serializeScriptData(publicEnv)};`,
          }}
        />
        <AppProviders>
          <AppShell>{children}</AppShell>
        </AppProviders>
        <ScrollRestoration />
        <Scripts />
      </body>
    </html>
  )
}

export default function Root() {
  return (
    <ReactRouterAppRoutingBridge>
      <Outlet />
    </ReactRouterAppRoutingBridge>
  )
}

export function ErrorBoundary({ error }: { error: unknown }) {
  const title = isRouteErrorResponse(error)
    ? error.status === 404
      ? '404'
      : 'Error'
    : 'Error'
  const description = isRouteErrorResponse(error)
    ? error.statusText || 'The request could not be completed.'
    : error instanceof Error
      ? error.message
      : 'An unexpected error occurred.'

  return (
    <html lang="en">
      <head>
        <title>{title} · {SITE_NAME}</title>
      </head>
      <body className="grid min-h-screen place-items-center bg-background p-6 text-foreground">
        <div className="w-full max-w-lg rounded-2xl border border-border bg-card p-6 shadow-sm">
          <div className="text-sm font-medium text-muted-foreground">{SITE_NAME}</div>
          <h1 className="mt-2 text-2xl font-semibold">{title}</h1>
          <p className="mt-2 text-sm text-muted-foreground">{description}</p>
        </div>
        <Scripts />
      </body>
    </html>
  )
}

